export const VEHICLE_FIELDS=['capacity','baseConsumption','curbMass','maxDcPower','maxAcPower','dcConnector','acConnector'];
export const STARTER={id:'atto3',name:'BYD ATTO 3',year:2025,capacity:60.48,baseConsumption:23,curbMass:1750,maxDcPower:95,maxAcPower:11,dcConnector:'CCS2',acConnector:'Type2'};
export function validateVehicle(p){if(!p.name?.trim()||p.name.length>80)throw Error('Enter a vehicle name (up to 80 characters).');for(const [k,min,max] of [['year',1990,2100],['capacity',5,250],['baseConsumption',5,80],['curbMass',500,5000],['maxDcPower',0,500],['maxAcPower',0,43]])if(!Number.isFinite(p[k])||p[k]<min||p[k]>max)throw Error('Check '+k+' — expected '+min+' to '+max+'.');if(!['CCS2','none'].includes(p.dcConnector)||!['Type2','none'].includes(p.acConnector))throw Error('Unsupported connector.');if(p.dcConnector==='none'&&p.acConnector==='none')throw Error('Enable at least one supported connector.');if(p.dcConnector!=='none'&&p.maxDcPower<=0||p.acConnector!=='none'&&p.maxAcPower<=0)throw Error('Enter a charging limit for each enabled connector.');return p;}
export function loadGarage(raw,legacy={}){try{const g=JSON.parse(raw);if(!Array.isArray(g.profiles)||!g.profiles.length||g.profiles.length>30)throw Error();g.profiles.forEach(p=>{validateVehicle(p);if(typeof p.id!=='string'||!p.id)throw Error();});if(new Set(g.profiles.map(p=>p.id)).size!==g.profiles.length)throw Error();if(!g.profiles.some(p=>p.id===g.activeId))g.activeId=g.profiles[0].id;return g;}catch{const p={...STARTER,capacity:legacy.capacity||STARTER.capacity,baseConsumption:legacy.baseConsumption||STARTER.baseConsumption};try{validateVehicle(p);}catch{return {profiles:[{...STARTER}],activeId:STARTER.id};}return {profiles:[p],activeId:p.id};}}
export function applyVehicle(settings,p){validateVehicle(p);return {...settings,...Object.fromEntries(VEHICLE_FIELDS.map(k=>[k,p[k]]))};}
